const fs = require('fs');
const usage = JSON.parse(fs.readFileSync('G:/AI/AIMemory/config/skill-usage.json', 'utf-8'));
const today = new Date('2026-07-19T00:00:00.000Z');
const cutoff = new Date(today.getTime() - 30*24*60*60*1000);

const underused = [];
for (const [name, s] of Object.entries(usage.skills)) {
  if (s.pinned) continue;
  if (name === 'uk-conventions') continue; // not a skill
  const lastUsed = s.last_agent_used_at ? new Date(s.last_agent_used_at) : null;
  const isOld = !lastUsed || lastUsed < cutoff;
  if (isOld && s.use_count < 3) {
    underused.push({ name, use_count: s.use_count, last_agent_used_at: s.last_agent_used_at, created_at: s.created_at, notes: s.notes });
  }
}
underused.sort((a,b) => (a.last_agent_used_at||'').localeCompare(b.last_agent_used_at||''));
for (const u of underused) {
  console.log(u.name, '| use_count=' + u.use_count, '| last_used=' + (u.last_agent_used_at || 'never'), '| created=' + u.created_at.slice(0,10), u.notes ? '| notes: ' + u.notes : '');
}
console.log('\\nTotal underused (non-pinned, non-exempt):', underused.length);
