const fs = require('fs');
const path = require('path');
const shardDir = 'G:/AI/AIMemory/facts_Topic/509424983';
const pageDir = 'G:/AI/AIMemory/wiki/concepts';

const pages = fs.readdirSync(pageDir).filter(f => f.endsWith('.md'));
for (const pf of pages) {
  const slug = pf.replace(/\.md\$/, '');
  const pageContent = fs.readFileSync(path.join(pageDir, pf), 'utf8');
  const sourcesMatch = pageContent.match(/sources:\s*\[(.*?)\]/s);
  const sources = sourcesMatch ? sourcesMatch[1].split(',').map(s => s.trim().replace(/^f_/, '')).filter(Boolean) : [];
  const updatedMatch = pageContent.match(/updated:\s*(\S+)/);
  const updated = updatedMatch ? updatedMatch[1] : '?';

  const shardPath = path.join(shardDir, slug + '.md');
  if (!fs.existsSync(shardPath)) {
    console.log(slug + ': NO SHARD FILE (updated=' + updated + ', sources=' + sources.length + ')');
    continue;
  }
  const shardContent = fs.readFileSync(shardPath, 'utf8');
  const shardIds = [...shardContent.matchAll(/\[f_([a-f0-9]{6})\]/g)].map(m => m[1]);
  const missing = shardIds.filter(id => !sources.includes(id));
  console.log(slug + ': updated=' + updated + ' shard=' + shardIds.length + ' sources=' + sources.length + ' missingFromSources=' + missing.length + (missing.length ? ' [' + missing.join(',') + ']' : ''));
}
"

