const SEG=30, HALF=15;
function schedule(L, circles, accelT, D){
  const alpha = 30/(L*L);
  const Dmin  = circles*360;
  const a=1/(2*alpha), b=0.5*accelT, c=-Math.max(60,Dmin);
  const v0=(-b+Math.sqrt(b*b-4*a*c))/(2*a);
  const accelDist=0.5*v0*accelT, decelDist=v0*v0/(2*alpha);
  const cruiseDist=Math.max(0,D-accelDist-decelDist);
  const cruiseT=cruiseDist/v0, decelT=v0/alpha;
  const total=accelT+cruiseT+decelT;
  // 由停止往回推每一聲 click（距停止 d = 15,45,75...）
  const back=[]; for(let k=0;k<12;k++){ const d=HALF+k*SEG; if(d>decelDist) break;
    back.push({d, tau: Math.sqrt(2*d/alpha)}); }
  return {alpha,v0,total,decelT,back};
}
