/** 機械式剝註解：整行註解直接丟、行尾註解在引號成對時才剝。不挑句子。 */
function stripComments(numberedLines) {
  const out = [];
  for (const { n, l } of numberedLines) {
    if (/^\s*(\/\/|\/\*|\*\/|\*(?!\w))/.test(l)) continue;
    let line = l;
    const i = line.indexOf("//");
    if (i > 0) {
      const before = line.slice(0, i);
      const q = (before.match(/"/g) || []).length, s = (before.match(/'/g) || []).length,
            b = (before.match(/`/g) || []).length;
      if (q % 2 === 0 && s % 2 === 0 && b % 2 === 0) line = before.replace(/\s+$/, "");
    }
    if (line.trim() === "") continue;
    out.push({ n, l: line });
  }
  return out;
}

